import six
from kodi_six import xbmc

from elementum.logger import log


class InfoTagHelper(object):
    @staticmethod
    def _is_none_or_empty(value):
        return value is None or (isinstance(value, six.string_types) and value == '')


    @staticmethod
    def _to_int(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            return None


    @staticmethod
    def _to_float(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return None


    @staticmethod
    def _to_list(value):
        if isinstance(value, (tuple, list)):
            return list(value)
        return [value]


    @classmethod
    def apply_video(cls, info_tag, info_labels):
        labels = info_labels or {}

        def _set(method_name, value, converter=None):
            if cls._is_none_or_empty(value):
                log.debug("Value %s: %s is None or empty", method_name, value)
                return
            if converter:
                value = converter(value)
                if value is None:
                    log.debug("Could not convert %s: %s to %s", method_name, value, converter.__name__)
                    return
            try:
                setter = getattr(info_tag, method_name, None)
                if setter:
                    setter(value)
            except Exception:
                log.error("Exception while setting %s to %s", method_name, value)
                import traceback
                log.error(traceback.format_exc())
                pass

        _set('setCountries', labels.get('country', ''), cls._to_list)
        _set('setDateAdded', labels.get('dateadded', ''))
        _set('setDbId', labels.get('dbid', ''), cls._to_int)
        _set('setDirectors', labels.get('director', ''), cls._to_list)
        _set('setDuration', labels.get('duration', ''), cls._to_int)
        _set('setEpisode', labels.get('episode', ''), cls._to_int)
        _set('setFirstAired', labels.get('aired', ''))
        _set('setGenres', labels.get('genre', ''), cls._to_list)
        _set('setIMDBNumber', labels.get('imdbnumber', ''))
        _set('setLastPlayed', labels.get('lastplayed', ''))
        _set('setMediaType', labels.get('mediatype', ''))
        _set('setMpaa', labels.get('mpaa', ''))
        _set('setOriginalTitle', labels.get('originaltitle', ''))
        _set('setPath', labels.get('path', ''))
        _set('setPlaycount', labels.get('playcount', ''), cls._to_int)
        _set('setPlot', labels.get('plot', ''))
        _set('setPlotOutline', labels.get('plotoutline', ''))
        _set('setPremiered', labels.get('premiered', ''))
        _set('setRating', labels.get('rating', ''), cls._to_float)
        _set('setSeason', labels.get('season', ''), cls._to_int)
        _set('setSet', labels.get('set', ''))
        _set('setSetId', labels.get('setid', ''), cls._to_int)
        _set('setSetOverview', labels.get('setoverview', ''))
        _set('setSortTitle', labels.get('sorttitle', ''))
        _set('setStudios', labels.get('studio', ''), cls._to_list)
        _set('setTagLine', labels.get('tagline', ''))
        _set('setTags', labels.get('tag', ''), cls._to_list)
        _set('setTitle', labels.get('title', ''))
        _set('setTrailer', labels.get('trailer', ''))
        _set('setTvShowStatus', labels.get('status', ''))
        _set('setTvShowTitle', labels.get('tvshowtitle', ''))
        _set('setUserRating', labels.get('userrating', ''), cls._to_int)
        _set('setVotes', labels.get('votes', ''), cls._to_int)
        _set('setWriters', labels.get('writer', ''), cls._to_list)
        _set('setYear', labels.get('year', ''), cls._to_int)


    @classmethod
    def apply_cast(cls, info_tag, castmembers):
        actors = []
        for castmember in castmembers:
            order = cls._to_int(castmember.get('order', -1))
            if order is None:
                order = -1
            actors.append(
                xbmc.Actor(
                    name=castmember.get('name', ''),
                    role=castmember.get('role', ''),
                    thumbnail=castmember.get('thumbnail', ''),
                    order=order,
                )
            )
        info_tag.setCast(actors)


    @classmethod
    def apply_stream_info(cls, info_tag, stream_info):
        if not stream_info:
            return

        for type_, values in stream_info.items():
            if type_ == "video":
                video_stream_detail = xbmc.VideoStreamDetail(
                    width=values.get('width', 0),
                    height=values.get('height', 0),
                    aspect=values.get('aspect', 0),
                    duration=values.get('duration', 0),
                    codec=values.get('codec', ''),
                    language=values.get('language', ''),
                )
                info_tag.addVideoStream(video_stream_detail)
            elif type_ == "audio":
                audio_stream_detail = xbmc.AudioStreamDetail(
                    language=values.get('language', ''),
                    codec=values.get('codec', ''),
                    channels=values.get('channels', -1),
                )
                info_tag.addAudioStream(audio_stream_detail)
            elif type_ == "subtitle":
                subtitle_stream_detail = xbmc.SubtitleStreamDetail(
                    language=values.get('language', ''),
                )
                info_tag.addSubtitleStream(subtitle_stream_detail)
